# /// script
# requires-python = ">=3.11,<3.14"
# dependencies = ["relationalai==1.30.1"]
# ///
"""urn:probe:pl12: the model's rules as PyRel requirements (DuckDB version).

Each rule is shown as the requirement it is, `m.where(<domain>).require(<check>)`.
Local DuckDB does not enforce require, so each rule is evaluated in its denial form,
`m.where(<domain>, <not check>)`: the facts that would violate it. The logic reasoner
(direct LQP compiler) lowers a requirement to that same condition; the LQP version of
this program states the same rules for an engine to enforce.

Usage: python THIS_FILE POPULATION.json
Generated by `gnd export pyrel --rules duckdb`. Do not edit; change the model instead.
"""
from __future__ import annotations

import json
import os
import re
import sys
import tempfile

SCHEMA = 'urn_probe_pl12'
RULES = json.loads('[\n {\n  "id": "member#0",\n  "family": "uniqueness",\n  "modality": "alethic",\n  "witness": [\n   "$level_1",\n   "$level_2",\n   "$person",\n   "$team_1",\n   "$team_2"\n  ],\n  "vacuous_when": [\n   "any",\n   [\n    "member"\n   ]\n  ],\n  "requires": 2\n },\n {\n  "id": "person_has_tag#0",\n  "family": "mandatory",\n  "modality": "alethic",\n  "witness": [\n   "$x"\n  ],\n  "vacuous_when": [\n   "any",\n   [\n    "person_has_tag"\n   ]\n  ],\n  "requires": 1\n },\n {\n  "id": "lead_is_member",\n  "family": "subset",\n  "modality": "alethic",\n  "witness": [\n   "$k0",\n   "$k1"\n  ],\n  "vacuous_when": [\n   "all",\n   [\n    "lead",\n    "member"\n   ]\n  ],\n  "requires": 1\n },\n {\n  "id": "tag_values",\n  "family": "value",\n  "modality": "alethic",\n  "witness": [\n   "$x"\n  ],\n  "vacuous_when": [\n   "all",\n   [\n    "person_has_tag",\n    "team_badge"\n   ]\n  ],\n  "requires": 1\n },\n {\n  "id": "pid_values",\n  "family": "value",\n  "modality": "alethic",\n  "witness": [\n   "$x"\n  ],\n  "vacuous_when": [\n   "all",\n   [\n    "member",\n    "lead",\n    "person_has_tag"\n   ]\n  ],\n  "requires": 1\n },\n {\n  "id": "level3_leads_t1",\n  "family": "guarded",\n  "modality": "alethic",\n  "witness": [\n   "$p",\n   "$t"\n  ],\n  "vacuous_when": [\n   "any",\n   [\n    "member"\n   ]\n  ],\n  "requires": 1\n },\n {\n  "id": "level_cap",\n  "family": "guarded",\n  "modality": "alethic",\n  "witness": [\n   "$l",\n   "$p",\n   "$t"\n  ],\n  "vacuous_when": [\n   "any",\n   [\n    "member"\n   ]\n  ],\n  "requires": 1\n },\n {\n  "id": "lead_has_badge",\n  "family": "guarded",\n  "modality": "alethic",\n  "witness": [\n   "$p",\n   "$t"\n  ],\n  "vacuous_when": [\n   "any",\n   [\n    "lead"\n   ]\n  ],\n  "requires": 1\n }\n]')
LIMIT = 1 << 20


def read_population(path):
    with open(path, 'rb') as handle:
        raw = handle.read(LIMIT + 1)
    if len(raw) > LIMIT:
        raise ValueError('population larger than 1 MiB')
    document = json.loads(raw)
    if not isinstance(document.get('facts'), dict):
        raise KeyError('facts')
    for fact_type, rows_ in document['facts'].items():
        seen = set()
        for row in rows_:
            key = json.dumps(row, sort_keys=True)
            if key in seen:
                raise ValueError(f'duplicate rows in {fact_type}: PyRel relations are sets, so '
                                 'repeated facts cannot be checked here; GND reports them')
            seen.add(key)
    return document


def load(m, relation, rows, roles):
    if rows:
        m.define(*[relation(*[row[r] for r in roles]) for row in rows])


def rows(query):
    return sorted(list(row) for row in query.to_df().itertuples(index=False, name=None))


def build(population, config):
    from relationalai.semantics import Boolean, Field, Float, Integer, Model, String, not_  # noqa: F401
    m = Model(SCHEMA, config=config)
    facts = population['facts']
    instances = population.get('instances', {})
    found = {}


    # ---- facts: one relationship per fact type
    # {Person} is in {Team} at {Level}
    member = m.Relationship(fields=[Field('person', String), Field('team', String), Field('level', Integer)], short_name='member')
    load(m, member, facts.get('member', []), ('person', 'team', 'level'))
    # {Person} leads {Team}
    lead = m.Relationship(fields=[Field('person', String), Field('team', String)], short_name='lead')
    load(m, lead, facts.get('lead', []), ('person', 'team'))
    # {Person} has {Tag}
    person_has_tag = m.Relationship(fields=[Field('person', String), Field('tag', String)], short_name='person_has_tag')
    load(m, person_has_tag, facts.get('person_has_tag', []), ('person', 'tag'))
    # {Team} has badge {Tag}
    team_badge = m.Relationship(fields=[Field('team', String), Field('badge', String)], short_name='team_badge')
    load(m, team_badge, facts.get('team_badge', []), ('team', 'badge'))

    # ---- helper relations the rules refer to
    # every person mentioned in any fact, plus the population's instances roster
    person_any = m.Relationship(fields=[Field('member', String)], short_name='person_any')
    x = String.ref()
    m.where(member(x, String.ref(), Integer.ref())).define(person_any(x))
    m.where(lead(x, String.ref())).define(person_any(x))
    m.where(person_has_tag(x, String.ref())).define(person_any(x))
    for value in [v for key in ['person'] for v in instances.get(key, [])]:
        m.define(person_any(value))
    # every person_id mentioned in any fact, plus the population's instances roster
    person_id_any = m.Relationship(fields=[Field('member', String)], short_name='person_id_any')
    x = String.ref()
    m.where(member(x, String.ref(), Integer.ref())).define(person_id_any(x))
    m.where(lead(x, String.ref())).define(person_id_any(x))
    m.where(person_has_tag(x, String.ref())).define(person_id_any(x))
    for value in [v for key in ['person_id', 'person'] for v in instances.get(key, [])]:
        m.define(person_id_any(value))
    # every tag mentioned in any fact, plus the population's instances roster
    tag_any = m.Relationship(fields=[Field('member', String)], short_name='tag_any')
    x = String.ref()
    m.where(person_has_tag(String.ref(), x)).define(tag_any(x))
    m.where(team_badge(String.ref(), x)).define(tag_any(x))
    for value in [v for key in ['tag'] for v in instances.get(key, [])]:
        m.define(tag_any(value))
    # tag_values: the declared list of allowed values
    tag_values_allowed = m.Relationship(fields=[Field('value', String)], short_name='tag_values_allowed')
    m.define(*[tag_values_allowed(v) for v in ['a', 'b']])
    # pid_values: the declared list of allowed values
    pid_values_allowed = m.Relationship(fields=[Field('value', String)], short_name='pid_values_allowed')
    m.define(*[pid_values_allowed(v) for v in ['p1', 'p2', 'p3']])

    # ---- rules: `require` says what must hold
    # member#0 (must): q
    level_1, level_2, person, team_1, team_2 = Integer.ref(), Integer.ref(), String.ref(), String.ref(), String.ref()
    #   rule:      m.where(member(person, team_1, level_1), member(person, team_2, level_2)).require(team_1 == team_2, level_1 == level_2)
    #   violation: the facts that match the domain and fail the check
    found['member#0'] = rows(m.where(member(person, team_1, level_1), member(person, team_2, level_2), not_(team_1 == team_2, level_1 == level_2)).select(level_1, level_2, person, team_1, team_2))
    # person_has_tag#0 (must): q
    x_ = String.ref()
    #   rule:      m.where(person_any(x_)).require(person_has_tag(x_, String.ref()))
    #   violation: the facts that match the domain and fail the check
    found['person_has_tag#0'] = rows(m.where(person_any(x_), not_(person_has_tag(x_, String.ref()))).select(x_))
    # lead_is_member (must): lead_is_member
    k0, k1 = String.ref(), String.ref()
    #   rule:      m.where(lead(k0, k1)).require(member(k0, k1, Integer.ref()))
    #   violation: the facts that match the domain and fail the check
    found['lead_is_member'] = rows(m.where(lead(k0, k1), not_(member(k0, k1, Integer.ref()))).select(k0, k1))
    # tag_values (must): tag_values
    x_ = String.ref()
    #   rule:      m.where(tag_any(x_)).require(tag_values_allowed(x_))
    #   violation: the facts that match the domain and fail the check
    found['tag_values'] = rows(m.where(tag_any(x_), not_(tag_values_allowed(x_))).select(x_))
    # pid_values (must): pid_values
    x_ = String.ref()
    #   rule:      m.where(person_id_any(x_)).require(pid_values_allowed(x_))
    #   violation: the facts that match the domain and fail the check
    found['pid_values'] = rows(m.where(person_id_any(x_), not_(pid_values_allowed(x_))).select(x_))
    # level3_leads_t1 (must): level3_leads_t1
    p, t = String.ref(), String.ref()
    #   rule:      m.where(member(p, t, 3)).require(lead(p, 't1'))
    #   violation: the facts that match the domain and fail the check
    found['level3_leads_t1'] = rows(m.where(member(p, t, 3), not_(lead(p, 't1'))).select(p, t))
    # level_cap (must): level_cap
    l, p, t = Integer.ref(), String.ref(), String.ref()
    #   rule:      m.where(member(p, t, l)).require(l <= 5)
    #   violation: the facts that match the domain and fail the check
    found['level_cap'] = rows(m.where(member(p, t, l), l > 5).select(l, p, t))
    # lead_has_badge (must): lead_has_badge
    p, t = String.ref(), String.ref()
    #   rule:      m.where(lead(p, t)).require(team_badge(t, 'a'))
    #   violation: the facts that match the domain and fail the check
    found['lead_has_badge'] = rows(m.where(lead(p, t), not_(team_badge(t, 'a'))).select(p, t))
    return found


def report(population, found):
    """One line per rule; exit 1 on any must-rule violation, else 2 if a rule was vacuous, else 0.

    A fact list the input does not provide is empty here, as in GND's checker.
    """
    facts = population['facts']
    violated = vacuous = False
    for rule in RULES:
        name = rule['id']
        mode, lists = rule['vacuous_when']
        empty = [not facts.get(ref) for ref in lists]
        if lists and (any(empty) if mode == 'any' else all(empty)):
            print(f'{name}  vacuous  (no facts for it to apply to)')
            vacuous = True
            continue
        hits = witnesses(rule, found[name])
        if not hits:
            print(f'{name}  OK')
        status = 'violated' if rule['modality'] == 'alethic' else 'warning'
        for hit in hits:
            print(f'{name}  {status}  {json.dumps(hit, sort_keys=True)}')
        violated = violated or (bool(hits) and status == 'violated')
    return 1 if violated else 2 if vacuous else 0


def witnesses(rule, found):
    """Shape each violating row the way GND's checker reports it."""
    names = rule['witness']
    if rule['family'] == 'guarded':
        return [dict(zip(names, row)) for row in found]
    if rule['family'] in ('mandatory', 'subset'):
        return [list(row) for row in found]
    if rule['family'] == 'value':
        return [row[0] for row in found]
    if rule['family'] == 'uniqueness':
        # GND reports one verdict per rule listing every fact that shares a key with another.
        facts_seen = {}
        for row in found:
            values = dict(zip(names, row))
            key = {k[1:]: v for k, v in values.items() if not re.search(r'_[12]$', k)}
            for suffix in ('_1', '_2'):
                fact = dict(key)
                fact.update({k[1:-2]: v for k, v in values.items() if k.endswith(suffix)})
                facts_seen[json.dumps(fact, sort_keys=True)] = fact
        return [[facts_seen[k] for k in sorted(facts_seen)]] if facts_seen else []
    return [list(row) for row in found]


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 1:
        print('usage: python THIS_FILE POPULATION.json', file=sys.stderr)
        return 64
    try:
        population = read_population(argv[0])
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(f'{argv[0]}: not a readable population ({type(error).__name__}: {error})', file=sys.stderr)
        return 3
    try:
        with tempfile.TemporaryDirectory(prefix='gnd-rules-') as directory:
            os.environ['RAI_BUILD_DIR'] = directory   # explicit local build state; no remote discovery
            from relationalai.config import Config
            config = Config(connections={'local': {'type': 'duckdb', 'path': ':memory:'}},
                            default_connection='local',
                            deployment={'schema': SCHEMA, 'auto_deploy': True})
            found = build(population, config)
    except Exception as error:  # noqa: BLE001 -- a crash must never read as a rule violation (exit 1)
        print(f'PyRel execution failed: {type(error).__name__}: {error}', file=sys.stderr)
        return 70
    return report(population, found)


if __name__ == '__main__':
    raise SystemExit(main())

